import{_ as s,c as i,o as e,a2 as t}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"markActivitySeen","description":"Acknowledge explicit entries, or the rows a captured watermark\'s view held (its filters and search).","frontmatter":{"editLink":false,"rawMarkdown":"# markActivitySeen\\n\\nAcknowledge explicit entries, or the rows a captured watermark\'s view held (its filters and search).\\nNever called by paging, filtering, or export.\\n\\n## Import\\n\\n```ts\\nimport { markActivitySeen } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await markActivitySeen({ config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction markActivitySeen(parameters: MarkActivitySeenParameters): Promise<ActivityAcknowledgement>\\n```\\n\\n## Returns\\n\\n`Promise<ActivityAcknowledgement>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nThe account whose activity is acknowledged. Defaults to the active account.\\n\\n```ts\\nconst result = await markActivitySeen({\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `ids`\\n\\n- **Type:** `readonly string[] | undefined`\\n- **Required:** no\\n\\nThe activity entries to acknowledge explicitly. Mutually exclusive with `watermark`.\\n\\n```ts\\nconst result = await markActivitySeen({\\n  ids, // [!code focus]\\n});\\n```\\n\\n### `watermark`\\n\\n- **Type:** `string | undefined`\\n- **Required:** no\\n\\nA `watermark` captured from an activity page; acknowledges everything present when that page was created. Mutually exclusive with `ids`.\\n\\n```ts\\nconst result = await markActivitySeen({\\n  watermark, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await markActivitySeen({\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/views/markActivitySeen.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/views/markActivitySeen.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/views/markActivitySeen.md","rawMarkdownTitle":"markActivitySeen","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/views/markActivitySeen.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"views","action":"markActivitySeen"},"relativePath":"sdk/actions/views/markActivitySeen.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/views/markActivitySeen.md"};function r(l,a,o,h,c,d){return e(),i("div",null,[...a[0]||(a[0]=[t("",34)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
